        // Search functionality setup
        function setupSearchFunctionality(inputId, suggestionsId) {
            const searchInput = document.getElementById(inputId);
            const suggestionsContainer = document.getElementById(suggestionsId);

            if (!searchInput || !suggestionsContainer) return;

            // Input event with debouncing
            searchInput.addEventListener('input', function(e) {
                const query = e.target.value.trim();

                // Clear previous timeout
                clearTimeout(searchTimeout);

                // Hide suggestions if query is empty
                if (query.length === 0) {
                    suggestionsContainer.classList.add('hidden');
                    return;
                }

                // Show loading state
                const suggestionsContent = suggestionsContainer.querySelector('.search-suggestions');
                suggestionsContent.innerHTML = '<div class="p-4 text-center text-gray-500">Searching...</div>';
                suggestionsContainer.classList.remove('hidden');

                // Set new timeout for API call
                searchTimeout = setTimeout(() => {
                    performSearch(query, suggestionsContent);
                }, searchDelay);
            });

            // Hide suggestions when clicking outside
            document.addEventListener('click', function(e) {
                if (!e.target.closest('#' + inputId) && !e.target.closest('#' + suggestionsId)) {
                    suggestionsContainer.classList.add('hidden');
                }
            });

            // Handle suggestion item click
            suggestionsContainer.addEventListener('click', function(e) {
                const suggestionItem = e.target.closest('.suggestion-item');
                if (suggestionItem) {
                    const searchName = suggestionItem.getAttribute('data-name');
                    const seoName = suggestionItem.getAttribute('data-seo');
                    const searchType = suggestionItem.getAttribute('data-type');

                    if (searchType === 'Product') {
                        window.location.href = '/Product/' + seoName;
                    } else if (searchType === 'Category') {
                        window.location.href = '/Category/' + seoName;
                    } else if (searchType === 'Publisher') {
                        window.location.href = '/Publisher/' + seoName;
                    } else if (searchType === 'School') {
                        window.location.href = '/' + seoName;
                    } else if (searchType === 'Blog') {
                        window.location.href = '/Blog/' + seoName;
                    } else {
                        // Default search behavior
                        window.location.href = '/SearchResult?s' + encodeURIComponent(searchName);
                    }
                }
            });
        }

        // Perform search API call
        function performSearch(query, suggestionsContent) {
            $.ajax({

                type: "GET",
        url: BaseURL + "GetSearchResultByCache2",
        data: { searchphrase: query },
                success: function(response) {
                    displaySearchSuggestions(response, suggestionsContent);
                },
                error: function(xhr, status, error) {
                    console.error('Search error:', error);
                    suggestionsContent.innerHTML = '<div class="p-4 text-center text-red-500">Search failed. Please try again.</div>';
                }
            });
        }

        // Display search suggestions
        function displaySearchSuggestions(response, suggestionsContent) {
            if (!response || response.response !== "1" || !response.SearchList) {
                suggestionsContent.innerHTML = '<div class="p-4 text-center text-gray-500">No results found</div>';
                return;
            }

            let suggestionsHTML = '';

            response.SearchList.forEach(group => {
                if (group.SearchItemList && group.SearchItemList.length > 0) {
                    suggestionsHTML += `
                        <div class="suggestion-group mb-3">
                            <div class="px-3 py-2 bg-gray-50 border-b border-gray-200 sticky top-0 z-10">
                                <h3 class="font-semibold text-gray-700 text-sm">${group.DisplayName}</h3>
                            </div>
                            <div class="space-y-1 mt-2">
                    `;

                    // Limit to 10 items per group for better UX
                    const itemsToShow = group.SearchItemList.slice(0, 10);

                    itemsToShow.forEach(item => {
                        const icon = group.DisplayName === 'Product' ? 'fa-cube' :
                                   group.DisplayName === 'Category' ? 'fa-th-large' : 'fa-search';

                        suggestionsHTML += `
                            <div class="suggestion-item px-3 py-2 rounded-lg flex items-center space-x-3"
                                 data-name="${item.SearchName}"
                                 data-seo="${item.SeoName}"
                                 data-type="${group.DisplayName}">
                                <i class="fas ${icon} text-gray-400 text-sm"></i>
                                <span class="text-sm text-gray-700 flex-1 truncate">${item.SearchName}</span>
                            </div>
                        `;
                    });

                    suggestionsHTML += `
                            </div>
                        </div>
                    `;
                }
            });

            if (suggestionsHTML === '') {
                suggestionsHTML = '<div class="p-4 text-center text-gray-500">No results found</div>';
            }

            suggestionsContent.innerHTML = suggestionsHTML;
        }


        const faqItems = document.querySelectorAll('.faq-item');
            faqItems.forEach(item => {
                const question = item.querySelector('h3');
                const answer = item.querySelector('.mt-4');
                const icon = item.querySelector('i');

                if (answer) answer.style.display = 'none';

                if (question) {
                    question.addEventListener('click', () => {
                        if (answer.style.display === 'none') {
                            answer.style.display = 'block';
                            if (icon) {
                                icon.classList.remove('fa-chevron-down');
                                icon.classList.add('fa-chevron-up');
                            }
                        } else {
                            answer.style.display = 'none';
                            if (icon) {
                                icon.classList.remove('fa-chevron-up');
                                icon.classList.add('fa-chevron-down');
                            }
                        }

                        faqItems.forEach(otherItem => {
                            if (otherItem !== item) {
                                const otherAnswer = otherItem.querySelector('.mt-4');
                                const otherIcon = otherItem.querySelector('i');
                                if (otherAnswer) otherAnswer.style.display = 'none';
                                if (otherIcon) {
                                    otherIcon.classList.remove('fa-chevron-up');
                                    otherIcon.classList.add('fa-chevron-down');
                                }
                            }
                        });
                    });
                }
            });
             // Stats counter (if exists)
            function animateCounter(elementId, targetValue, suffix = '') {
                const element = document.getElementById(elementId);
                if (!element) return;

                let currentValue = 0;
                const duration = 2000;
                const steps = 60;
                const increment = targetValue / steps;
                const stepTime = duration / steps;

                const timer = setInterval(() => {
                    currentValue += increment;

                    if (currentValue >= targetValue) {
                        currentValue = targetValue;
                        clearInterval(timer);
                    }

                    let displayValue = Math.round(currentValue);

                    if (elementId === 'parentCount') {
                        if (displayValue >= 100000) {
                            element.textContent = '1 Lakh+';
                        } else if (displayValue >= 1000) {
                            element.textContent = displayValue.toLocaleString() + suffix;
                        } else {
                            element.textContent = displayValue + suffix;
                        }
                    } else {
                        if (displayValue >= 100) {
                            element.textContent = '100+';
                        } else {
                            element.textContent = displayValue + suffix;
                        }
                    }
                }, stepTime);
            }

            const observer1 = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        animateCounter('schoolCount', 100, '+');
                        animateCounter('parentCount', 100000, '+');
                        observer1.unobserve(entry.target);
                    }
                });
            }, { threshold: 0.5 });

            const statsSection = document.querySelector('.stat-card');
            if (statsSection) {
                observer1.observe(statsSection);
            }

        function SignOut() {
            fetch('/Home/ClearSession', {
                method: 'POST'
            }).then(() => {
